"""Project Euler Problem 8: Largest Product in a Series"""

DIGITS = (
    ""
)


def solve(window: int = 13) -> int:
    best = 0
    for i in range(len(DIGITS) - window + 1):
        product = 1
        for ch in DIGITS[i : i + window]:
            product *= int(ch)
        best = max(best, product)
    return best


if __name__ == "__main__":
    print(solve())
